            for (i, y) in [0.08, 0.175, 0.27].iter().enumerate() { sym(q, [0.012, *y, 0.15, 0.13 - i as f64 * 0.0, y + 0.08, 0.164], if i == 1 { k(a, 1.1) } else { hi }); } // les abdominaux
            b(q, [-0.008, 0.08, 0.15, 0.008, 0.38, 0.166], d); sym(q, [0.03, 0.36, -0.168, 0.2, 0.52, -0.15], hi);
            b(q, [-0.24, 0.0, -0.154, 0.24, 0.03, 0.154], d); b(q, [-0.14, 0.58, -0.14, 0.14, 0.625, 0.14], d);
            let mut i = 0; let mut x = -0.2; while x < 0.21 { let c = if i % 2 == 0 { HIDE } else { RED }; // les ptéruges
                for z in [0.146, -0.158] { b(q, [x - 0.022, -0.24, z, x + 0.022, 0.0, z + 0.012], c); b(q, [x - 0.022, -0.25, z - 0.002, x + 0.022, -0.22, z + 0.014], a); } x += 0.05; i += 1; }
