            b(q, [-0.2, 0.04, 0.15, 0.2, 0.22, 0.164], a); b(q, [-0.2, 0.21, 0.162, 0.2, 0.226, 0.17], GOLD); // la pansière, bordée d'or
            for x in [-0.15, 0.15] { b(q, [x - 0.012, 0.1, 0.164, x + 0.012, 0.124, 0.17], GOLD); }
            b(q, [-0.13, 0.553, 0.148, 0.13, 0.57, 0.158], GOLD); b(q, [-0.14, 0.56, -0.14, 0.14, 0.62, 0.14], d); b(q, [-0.12, 0.62, -0.12, 0.12, 0.67, 0.12], a);
            for i in 0..3 { let y0 = -0.0 - i as f64 * 0.065; b(q, [-0.236, y0 - 0.072, -0.152, 0.236, y0, 0.154 + 0.006 * i as f64], if i % 2 == 0 { a } else { hi }); b(q, [-0.236, y0 - 0.074, 0.15, 0.236, y0 - 0.066, 0.158 + 0.006 * i as f64], d); }
